"""Writes tools/stats/cases_misc.txt: small closed-form functions (designs, densities, ridge, ...)."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = "S2=[2 0.5;0.5 1]; S3=[2 0.3 0.1;0.3 1.5 0.2;0.1 0.2 1]; Xm=[0.2 0.5;1 -0.3;0.7 0.9;-1 0.4]; "
L = ["# generated by make_misc_cases.py"]
for c in ["combnk(1:4,2)", "combnk(1:5,3)", "combnk(1:5,1)", "combnk(1:5,5)", "combnk(1:5,4)", "combnk(1:5,0)", "combnk((1:4)',2)", "combnk([10 20 30 40],3)", "combnk(1:20,2)", "combnk(1:6,2)", "combnk('abcd',2)",
          "combnk(1:3,5)", "combnk(A,2)", "combnk(1:4,2.5)", "combnk(1:18,17)", "combnk(1:17,15)"]:
    L.append(f"r = {c};")
for c in ["ff2n(1)", "ff2n(2)", "ff2n(3)", "ff2n(0)", "ff2n(4)", "ff2n([2 3])", "ff2n(-1)", "ff2n(2.5)", "fullfact([2 3])", "fullfact([2 3 2])", "fullfact([3;2])", "fullfact(4)", "fullfact([1 1])", "fullfact([2 0])",
          "fullfact([2 1.5])", "fullfact(int8([2 2]))", "fullfact(A)", "fullfact(single([2 2]))"]:
    L.append(f"r = {c};")
for c in ["mnpdf([1 2 1],[0.2 0.5 0.3])", "mnpdf([1 2 1;0 3 1],[0.2 0.5 0.3])", "mnpdf([1 2 1;0 3 1],[0.2 0.5 0.3;0.1 0.1 0.8])", "mnpdf([1 2 1],[0.2 0.5 0.3;0.1 0.1 0.8])", "mnpdf([1;2;1],[0.2;0.5;0.3])", "mnpdf([1 2 1],[0.2 0.5 0.4])",
          "mnpdf([1 2 1],[0.2 0.5])", "mnpdf([1 -2 1],[0.2 0.5 0.3])", "mnpdf([1 2.5 1],[0.2 0.5 0.3])", "mnpdf([0 0 0],[0.2 0.5 0.3])", "mnpdf([3 0],[1 0])", "mnpdf([3 1],[1 0])", "mnpdf(single([1 2 1]),[0.2 0.5 0.3])",
          "mnpdf([1 2 1;1 1 1;0 0 0],[0.2 0.5 0.3;0.2 0.5 0.3])", "mnpdf([],[])", "mnpdf([1 2])"]:
    L.append(f"r = {c};")
for c in ["mvnpdf([0.3 0.4])", "mvnpdf([0.3 0.4],[0 0])", "mvnpdf([0.3 0.4],[0 0],S2)", "mvnpdf(Xm,[0.5 0],S2)", "mvnpdf(Xm,0,S2)", "mvnpdf(Xm,[],S2)", "mvnpdf(Xm,[0.5 0],[2 3])", "mvnpdf(Xm,[0.5 0;0 0;1 1;0 1],S2)",
          "mvnpdf([0.3 0.4],[0.5 0;0 0;1 1],S2)", "mvnpdf((1:5)',0,2)", "mvnpdf((1:5)')", "mvnpdf([0.3 0.4 0.1],[0 0 0],S3)", "mvnpdf(Xm,[0.5 0],cat(3,S2,S2,S2,S2))", "mvnpdf(Xm,[0.5 0],[1 2;3 4])", "mvnpdf(Xm,[0.5 0],[1 0 0;0 1 0])",
          "mvnpdf(Xm,[0.5 0 0],S2)", "mvnpdf(Xm,[0.5 0],eye(3))", "mvnpdf(Xm,[0.5 0],[0 1])", "mvnpdf(Xm,[0.5 0],[1 1;1 1])", "mvnpdf(single(Xm),[0.5 0],S2)", "mvnpdf()", "mvnpdf(ones(2,2,2))", "mvnpdf(Xm,[1 2;3 4;5 6],S2)"]:
    L.append(f"r = {c};")
for c in ["mvtpdf([0.3 0.4],S2,5)", "mvtpdf(Xm,S2,5)", "mvtpdf(Xm,[1 0.3;0.3 1],[3;4;5;6])", "mvtpdf(Xm,[1 0.3;0.3 1],2.5)", "mvtpdf((1:4)',2,3)", "mvtpdf(Xm,[1 0.3;0.3 1],-1)", "mvtpdf(Xm,[1 2;2 1],3)", "mvtpdf(Xm,eye(3),3)", "mvtpdf(Xm,S2)",
          "mvtpdf(Xm,[1 0.3;0.3 1],[1 2])", "mvtpdf(single(Xm),[1 0.3;0.3 1],3)", "mvtpdf(Xm,[1 0.3 0;0.3 1 0],3)"]:
    L.append(f"r = {c};")
for c in ["leverage(A(:,2:3))", "leverage(A(:,2:3),'interactions')", "leverage(A(:,2))", "leverage(N(:,2:4))", "leverage(A(:,2),'quadratic')", "leverage(A(:,2:3),'constant')", "leverage(single(A(:,2:3)))", "leverage(A(:,2:3),'foo')"]:
    L.append(f"r = {c};")
for c in ["ridge(A(:,1),A(:,2:3),0.5)", "ridge(A(:,1),A(:,2:3),[0 0.1 1])", "ridge(A(:,1),A(:,2:3),0.5,0)", "ridge(A(:,1),A(:,2:3),[0 1],1)", "ridge(A(:,1),A(:,2:4),2,0)", "ridge(A(:,1),A(:,2),1)", "ridge(N(:,1),N(:,2:4),1)", "ridge(A(:,1),[A(:,2) ones(6,1)],1)",
          "ridge(A(:,1),A(:,2:3))", "ridge(A(1:5,1),A(:,2:3),1)", "ridge(A,A(:,2:3),1)", "ridge(A(:,1),A(:,2:3),1,2)", "ridge(single(A(:,1)),single(A(:,2:3)),1)"]:
    L.append(f"r = {c};")
for c in ["nancov(N)", "nancov(N,'pairwise')", "nancov(N,'complete')", "nancov(N,1)", "nancov(N,1,'pairwise')", "nancov(A(:,1),A(:,2))", "nancov(A(:,1))", "nancov([])", "nancov(zeros(0,3))", "nancov(5,6)", "nancov(A,'foo')", "nancov()", "nancov(A(:,1),A(1:3,2))", "nancov(cat(3,A,A))",
          "nancov(N,0,'pairwise')", "nancov(single(N))"]:
    L.append(f"r = {c};")
for c in ["tabulate([1 2 2 3 3 3])", "tabulate([1 2 2 3 3 3]')", "tabulate([3 1 1 NaN])", "tabulate([1 3 5])", "tabulate(int8([1 2 2 5]))", "tabulate([])", "tabulate(A)", "tabulate(single([1 2 2]))", "tabulate([0 0 1])"]:
    L.append(f"r = {c};")
for c in ["x(1:10)", "x(1:10)'", "[1 2 2 3 3 3]", "[1 1 1]", "[3 1 NaN 2]", "x(1:30)", "single([3 1 2 2])"]:
    L.append(f"[f_,x_] = ecdf({c}); r = {{f_,x_}};")
    L.append(f"[f_,x_,lo_,up_] = ecdf({c}); r = {{f_,x_,lo_,up_}};")
for c in ["ecdf(x(1:10),'Alpha',0.1)", "ecdf(x(1:10),'Function','survivor')", "ecdf(x(1:10),'Function','cumulative hazard')", "ecdf(x(1:10),'Bounds','on')", "ecdf(x(1:10),'Censoring',[zeros(1,8) 1 1])", "ecdf(x(1:10),'Frequency',[2 ones(1,9)])",
          "ecdf(x(1:10),'Function','foo')", "ecdf()", "ecdf(A)", "ecdf([])", "ecdf(NaN)"]:
    L.append(f"[f_,x_,lo_,up_] = {c}; r = {{f_,x_,lo_,up_}};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_misc.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
